-- Migration 020: Align topic cards with imported Shkolkovo task categories.
-- Titles are generated from data/raw/shkolkovo/task_N.json category values.

WITH topic_updates(task_number, title, description) AS (
    VALUES
        (1, 'Планиметрия', 'Площадь и периметр треугольника. Равнобедренная трапеция. Трапеция и ее свойства. Решение треугольника с помощью тригонометрии.'),
        (2, 'Векторы', 'Скалярное произведение векторов. Операции над векторами и координатами. Длина вектора.'),
        (3, 'Стереометрия', 'Вписанные и описанные тела. Отношение площадей поверхностей и отношение объемов тел. Прямоугольный параллелепипед. Правильная и прямоугольная пирамиды.'),
        (4, 'Введение в теорию вероятностей', 'Вероятность как отношение подходящих исходов ко всем исходам. Сумма вероятностей совместных событий. Произведение вероятностей независимых событий. Сумма вероятностей несовместных событий.'),
        (5, 'Сложные задачи по теории вероятностей', 'Умножение вероятностей вдоль цепочки событий. Комбинаторика. Условная вероятность. Задачи повышенного уровня сложности.'),
        (6, 'Простейшие уравнения', 'Логарифмические уравнения. Тригонометрические уравнения. Показательные уравнения. Иррациональные уравнения.'),
        (7, 'Преобразования и вычисления', 'Числовые тригонометрические выражения. Числовые логарифмические выражения. Буквенные тригонометрические выражения. Числовые иррациональные выражения.'),
        (8, 'Функция и её производная', 'Производная в точке касания как угловой коэффициент касательной. Производная и возрастание/убывание функции. Производная и точки экстремума функции.'),
        (9, 'Задачи прикладного характера', 'Задачи, сводящиеся к решению уравнений или вычислениям. Задачи, сводящиеся к решению неравенств. Прикладные модели и расчеты.'),
        (10, 'Текстовые задачи', 'Задачи на работу и производительность. Задачи на движение по воде. Задачи на прямолинейное движение. Задачи на проценты.'),
        (11, 'Графики функций', 'График показательной функции. График логарифмической функции. Комбинации прямой и графика другой функции. График обратной пропорциональности.'),
        (12, 'Исследование функции через производную', 'Поиск точек экстремума у элементарных функций. Поиск наибольшего/наименьшего значения у элементарных функций. Исследование смешанных функций.'),
        (13, 'Уравнения', 'Тригонометрические уравнения. Показательные и логарифмические уравнения. Отбор корней на отрезке.'),
        (14, 'Стереометрия', 'Построение сечений. Многогранники: пирамида и призма. Угол между плоскостями. Тела вращения: шар, цилиндр, конус.'),
        (15, 'Неравенства', 'Логарифмические неравенства. Показательные неравенства. Метод рационализации. Метод интервалов.'),
        (16, 'Экономические задачи', 'Банковский кредит. Дифференцированные и аннуитетные платежи. Оптимизация выплат и финансовых схем.'),
        (17, 'Планиметрия', 'Доказательства и вычисления в планиметрии. Признаки равенства треугольников. Окружности, биссектрисы, подобие и площади.'),
        (18, 'Задачи с параметром', 'Алгебраические задачи с параметром. Аналитические методы. Замены. Графические методы.'),
        (19, 'Задачи на теорию чисел', 'Инварианты и полуинварианты. Делимость чисел и признаки делимости. Целые числа и числовые конструкции.')
)
UPDATE topics
SET
    title = topic_updates.title,
    description = topic_updates.description
FROM topic_updates
WHERE topics.task_number = topic_updates.task_number;
